css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; animation: hourglass calc(var(--loader-speed) * 2.4) cubic-bezier(.68, 0, .32, 1) infinite; }
.loader::before, .loader::after { content: ''; position: absolute; left: 0; width: 0; height: 0; border-left: calc(var(--loader-size) / 2) solid transparent; border-right: calc(var(--loader-size) / 2) solid transparent; }
.loader::before { top: 0; border-top: calc(var(--loader-size) / 2) solid var(--accent); }
.loader::after { bottom: 0; border-bottom: calc(var(--loader-size) / 2) solid var(--accent-2); }
@keyframes hourglass { 0%, 35% { transform: rotate(0deg); } 50%, 85% { transform: rotate(180deg); } 100% { transform: rotate(360deg); } }
